/* =============================================
   Tactile Tic-Tac-Toe — Styles
   ============================================= */

/* CSS Custom Properties */
:root {
  --bg-page: #0f172a;
  --bg-surface: #1e293b;
  --bg-cell: #334155;
  --bg-cell-hover: #475569;
  --accent-x: #38bdf8;
  --accent-o: #f472b6;
  --accent-win: #22c55e;
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.3);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.4);
  --radius: 12px;
  --transition: 200ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

/* App Layout */
.app {
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* Header */
.header {
  text-align: center;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.25rem;
}

.subtitle {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

/* Controls */
.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.mode-toggle {
  display: flex;
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 0.25rem;
  gap: 0.25rem;
}

.mode-btn {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 600;
  padding: 0.5rem 0.875rem;
  border-radius: calc(var(--radius) - 4px);
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
}

.mode-btn.active {
  background: var(--bg-cell);
  color: var(--text-primary);
}

.mode-btn:hover:not(.active) {
  color: var(--text-primary);
}

.icon-btn {
  appearance: none;
  border: none;
  background: var(--bg-surface);
  color: var(--text-primary);
  font-size: 1.25rem;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), transform var(--transition);
}

.icon-btn:hover {
  background: var(--bg-cell);
  transform: scale(1.05);
}

/* Status Bar */
.status-bar {
  text-align: center;
}

.turn-indicator {
  display: inline-block;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.5rem 1rem;
  background: var(--bg-surface);
  border-radius: var(--radius);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}

.turn-indicator.x-turn {
  color: var(--accent-x);
  background: rgba(56, 189, 248, 0.12);
}

.turn-indicator.o-turn {
  color: var(--accent-o);
  background: rgba(244, 114, 182, 0.12);
}

.turn-indicator.win {
  color: var(--accent-win);
  background: rgba(34, 197, 94, 0.12);
}

/* Board */
.board-container {
  display: flex;
  justify-content: center;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  gap: 0.75rem;
  width: 100%;
  aspect-ratio: 1 / 1;
}

.cell {
  appearance: none;
  border: none;
  background: var(--bg-cell);
  border-radius: var(--radius);
  font-size: clamp(2rem, 8vw, 3.5rem);
  font-weight: 700;
  color: var(--text-primary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  box-shadow: var(--shadow-sm);
}

.cell:hover:not(:disabled) {
  background: var(--bg-cell-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.cell:disabled {
  cursor: default;
}

.cell.x {
  color: var(--accent-x);
}

.cell.o {
  color: var(--accent-o);
}

.cell.win {
  background: rgba(34, 197, 94, 0.25);
  color: var(--accent-win);
  animation: pulse 600ms ease-in-out;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.06); }
}

/* Scoreboard */
.scoreboard {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.score {
  background: var(--bg-surface);
  border-radius: var(--radius);
  padding: 0.75rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  transition: transform var(--transition);
}

.score-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-secondary);
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
}

.x-score .score-value { color: var(--accent-x); }
.o-score .score-value { color: var(--accent-o); }
.draw-score .score-value { color: var(--text-secondary); }

/* Actions */
.actions {
  display: flex;
  justify-content: center;
}

.reset-btn {
  appearance: none;
  border: none;
  background: var(--bg-cell);
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: var(--shadow-sm);
}

.reset-btn:hover {
  background: var(--bg-cell-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.reset-btn:active {
  transform: translateY(0);
}

/* Responsive */
@media (max-width: 360px) {
  .title { font-size: 1.5rem; }
  .board { gap: 0.5rem; }
  .cell { border-radius: 8px; }
}

/**
 * Audio module — lightweight Web Audio API wrapper for sound effects.
 * All sounds are synthesized in-code (no external assets).
 */

let audioCtx = null;
let enabled = true;

function ensureContext() {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if (audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
}

export function isEnabled() {
  return enabled;
}

export function toggle() {
  enabled = !enabled;
  return enabled;
}

export function playClick() {
  if (!enabled) return;
  ensureContext();
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(600, audioCtx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(300, audioCtx.currentTime + 0.1);
  gain.gain.setValueAtTime(0.0001, audioCtx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.15, audioCtx.currentTime + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.12);
  osc.connect(gain);
  gain.connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + 0.13);
}

export function playWin() {
  if (!enabled) return;
  ensureContext();
  const now = audioCtx.currentTime;
  [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(freq, now + i * 0.08);
    gain.gain.setValueAtTime(0.0001, now + i * 0.08);
    gain.gain.exponentialRampToValueAtTime(0.12, now + i * 0.08 + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.08 + 0.18);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start(now + i * 0.08);
    osc.stop(now + i * 0.08 + 0.2);
  });
}

export function playDraw() {
  if (!enabled) return;
  ensureContext();
  const now = audioCtx.currentTime;
  [440, 440].forEach((freq, i) => {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, now + i * 0.2);
    gain.gain.setValueAtTime(0.0001, now + i * 0.2);
    gain.gain.exponentialRampToValueAtTime(0.1, now + i * 0.2 + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.2 + 0.18);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start(now + i * 0.2);
    osc.stop(now + i * 0.2 + 0.2);
  });
}

/**
 * Storage module — persists scores across page refreshes via localStorage.
 */

const STORAGE_KEY = 'tactile-tic-tac-toe-scores';

export function loadScores() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (
        typeof parsed.x === 'number' &&
        typeof parsed.o === 'number' &&
        typeof parsed.draw === 'number'
      ) {
        return parsed;
      }
    }
  } catch {
    // ignore corrupt storage
  }
  return { x: 0, o: 0, draw: 0 };
}

export function saveScores(scores) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(scores));
  } catch {
    // ignore quota errors
  }
}

/**
 * AI module — unbeatable tic-tac-toe opponent using the minimax algorithm.
 *
 * The game tree for tic-tac-toe is small enough (max 9! = 362880 nodes) that
 * a full-depth minimax search is trivial in the browser. The AI evaluates:
 *   +10  if the maximizing player (AI) wins
 *   -10  if the minimizing player (human) wins
 *     0  for a draw
 *
 * The AI always picks the move with the highest score, guaranteeing it never loses.
 */

const WIN_SCORE = 10;
const LOSE_SCORE = -10;
const DRAW_SCORE = 0;

const WIN_LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
  [0, 3, 6], [1, 4, 7], [2, 5, 8], // cols
  [0, 4, 8], [2, 4, 6],            // diagonals
];

function checkWinner(board) {
  for (const [a, b, c] of WIN_LINES) {
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return board[a];
    }
  }
  if (board.every(cell => cell !== null)) return 'draw';
  return null;
}

function evaluate(board, depth) {
  const winner = checkWinner(board);
  if (winner === 'O') return WIN_SCORE - depth;   // AI wins — prefer faster wins
  if (winner === 'X') return LOSE_SCORE + depth;  // human wins — prefer slower losses
  if (winner === 'draw') return DRAW_SCORE;
  return null;
}

function minimax(board, depth, isMaximizing) {
  const score = evaluate(board, depth);
  if (score !== null) return score;

  if (isMaximizing) {
    let best = -Infinity;
    for (let i = 0; i < 9; i++) {
      if (board[i] === null) {
        board[i] = 'O';
        best = Math.max(best, minimax(board, depth + 1, false));
        board[i] = null;
      }
    }
    return best;
  } else {
    let best = Infinity;
    for (let i = 0; i < 9; i++) {
      if (board[i] === null) {
        board[i] = 'X';
        best = Math.min(best, minimax(board, depth + 1, true));
        board[i] = null;
      }
    }
    return best;
  }
}

/**
 * Returns the optimal index (0-8) for the AI ('O') to play.
 * If multiple moves tie, one is chosen at random to keep play varied.
 */
export function getBestMove(board) {
  const candidates = [];
  let bestScore = -Infinity;

  for (let i = 0; i < 9; i++) {
    if (board[i] === null) {
      board[i] = 'O';
      const score = minimax(board, 0, false);
      board[i] = null;

      if (score > bestScore) {
        bestScore = score;
        candidates.length = 0;
        candidates.push(i);
      } else if (score === bestScore) {
        candidates.push(i);
      }
    }
  }

  return candidates[Math.floor(Math.random() * candidates.length)];
}

/**
 * UI module — handles DOM updates, event listeners, and animations.
 */

const boardEl = document.getElementById('board');
const cells = Array.from(document.querySelectorAll('.cell'));
const turnIndicator = document.getElementById('turn-indicator');
const scoreXEl = document.getElementById('score-x');
const scoreOEl = document.getElementById('score-o');
const scoreDrawEl = document.getElementById('score-draw');
const mode2pBtn = document.getElementById('mode-2p');
const modeAiBtn = document.getElementById('mode-ai');
const resetBtn = document.getElementById('reset-btn');
const soundBtn = document.getElementById('sound-toggle');

export function getCells() {
  return cells;
}

export function getBoardElement() {
  return boardEl;
}

export function onCellClick(handler) {
  cells.forEach(cell => {
    cell.addEventListener('click', () => {
      const index = Number(cell.dataset.index);
      handler(index);
    });
  });
}

export function onResetClick(handler) {
  resetBtn.addEventListener('click', handler);
}

export function onModeChange(handler) {
  mode2pBtn.addEventListener('click', () => handler('2p'));
  modeAiBtn.addEventListener('click', () => handler('ai'));
}

export function onSoundToggle(handler) {
  soundBtn.addEventListener('click', handler);
}

export function renderCell(index, player) {
  const cell = cells[index];
  cell.textContent = player;
  cell.classList.add(player.toLowerCase());
  cell.disabled = true;
}

export function highlightWin(line) {
  line.forEach(index => cells[index].classList.add('win'));
}

export function setTurnIndicator(text, playerClass) {
  turnIndicator.textContent = text;
  turnIndicator.className = 'turn-indicator';
  if (playerClass) {
    turnIndicator.classList.add(playerClass);
  }
}

export function updateScores({ x, o, draw }) {
  scoreXEl.textContent = String(x);
  scoreOEl.textContent = String(o);
  scoreDrawEl.textContent = String(draw);
}

export function setMode(mode) {
  if (mode === '2p') {
    mode2pBtn.classList.add('active');
    modeAiBtn.classList.remove('active');
  } else {
    modeAiBtn.classList.add('active');
    mode2pBtn.classList.remove('active');
  }
}

export function setSoundIcon(enabled) {
  soundBtn.textContent = enabled ? '🔊' : '🔇';
}

export function resetBoard() {
  cells.forEach(cell => {
    cell.textContent = '';
    cell.classList.remove('x', 'o', 'win');
    cell.disabled = false;
  });
}

export function disableBoard() {
  cells.forEach(cell => {
    if (!cell.textContent) cell.disabled = true;
  });
}

/**
 * Game module — core logic and orchestration for Tactile Tic-Tac-Toe.
 *
 * Responsibilities:
 *   - Maintain board state and current turn
 *   - Detect wins and draws
 *   - Coordinate UI, AI, audio, and storage modules
 *   - Handle mode switching and game reset
 */

import * as ui from './ui.js';
import * as audio from './audio.js';
import * as storage from './storage.js';
import { getBestMove } from './ai.js';

/* ===================== Constants ===================== */

const WIN_LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
  [0, 3, 6], [1, 4, 7], [2, 5, 8], // columns
  [0, 4, 8], [2, 4, 6],            // diagonals
];

/* ===================== State ===================== */

let board = Array(9).fill(null);
let currentPlayer = 'X';
let gameOver = false;
let mode = '2p'; // '2p' | 'ai'
let scores = storage.loadScores();
let aiThinking = false;

/* ===================== Core Logic ===================== */

function checkWinner() {
  for (const line of WIN_LINES) {
    const [a, b, c] = line;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return { winner: board[a], line };
    }
  }
  if (board.every(cell => cell !== null)) {
    return { winner: 'draw', line: null };
  }
  return null;
}

function switchTurn() {
  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  updateTurnIndicator();
}

function updateTurnIndicator() {
  if (gameOver) return;
  const label = mode === 'ai' && currentPlayer === 'O'
    ? "Computer's turn"
    : `${currentPlayer}'s turn`;
  ui.setTurnIndicator(label, currentPlayer === 'X' ? 'x-turn' : 'o-turn');
}

function handleWin(result) {
  gameOver = true;
  if (result.winner === 'draw') {
    ui.setTurnIndicator("It's a draw!", 'win');
    scores.draw += 1;
    audio.playDraw();
  } else {
    ui.setTurnIndicator(`${result.winner} wins!`, 'win');
    ui.highlightWin(result.line);
    scores[result.winner.toLowerCase()] += 1;
    audio.playWin();
  }
  storage.saveScores(scores);
  ui.updateScores(scores);
  ui.disableBoard();
}

function makeMove(index) {
  if (gameOver || board[index] !== null || aiThinking) return false;

  board[index] = currentPlayer;
  ui.renderCell(index, currentPlayer);
  audio.playClick();

  const result = checkWinner();
  if (result) {
    handleWin(result);
    return true;
  }

  switchTurn();

  if (mode === 'ai' && currentPlayer === 'O' && !gameOver) {
    aiThinking = true;
    // Small delay makes the AI feel more natural and gives the browser time to render.
    setTimeout(() => {
      const move = getBestMove([...board]);
      aiThinking = false;
      makeMove(move);
    }, 350);
  }

  return true;
}

function resetGame() {
  board = Array(9).fill(null);
  currentPlayer = 'X';
  gameOver = false;
  aiThinking = false;
  ui.resetBoard();
  updateTurnIndicator();
}

function setMode(newMode) {
  mode = newMode;
  ui.setMode(mode);
  resetGame();
}

function toggleSound() {
  const enabled = audio.toggle();
  ui.setSoundIcon(enabled);
}

/* ===================== Initialization ===================== */

function init() {
  ui.updateScores(scores);
  ui.setMode(mode);
  ui.setSoundIcon(audio.isEnabled());
  updateTurnIndicator();

  ui.onCellClick(index => makeMove(index));
  ui.onResetClick(() => resetGame());
  ui.onModeChange(newMode => setMode(newMode));
  ui.onSoundToggle(() => toggleSound());
}

init();
